// --- inputs -----------------------------------------------------------------
let scraper = actions.webscraper;
let response_code = scraper._zt_meta.response.code;
let is_answered = response_code >= 200 && response_code < 300;
let raw_answer = is_answered ? scraper.choices[0].message.content : "";

// --- transform: keep display tags only, drop anything that can run ----------
// Elements removed together with everything inside them.
const blockedElements = ["script", "style", "iframe", "object", "embed", "form", "noscript", "template", "svg", "math", "head", "title", "textarea", "select", "button"];
// Tags kept, rebuilt with no attributes (links keep an https href only).
const allowedTags = ["p", "br", "strong", "em", "b", "i", "u", "ul", "ol", "li", "h3", "h4", "table", "thead", "tbody", "tr", "th", "td", "a"];

function rebuildTag(token) {
  let parts = token.match(/^<\s*(\/?)\s*([a-zA-Z][a-zA-Z0-9]*)([\s\S]*)>$/);
  if (!parts) return token.replace(/</g, "&lt;").replace(/>/g, "&gt;");
  let tagName = parts[2].toLowerCase();
  if (!allowedTags.includes(tagName)) return "";
  if (parts[1] === "/") return `</${tagName}>`;
  if (tagName !== "a") return `<${tagName}>`;
  let href = parts[3].match(/\bhref\s*=\s*["']?(https:\/\/[^"'\s<>]+)/i);
  if (!href) return "<a>";
  return `<a href="${href[1]}" target="_blank" rel="noopener noreferrer">`;
}

let answer_html = raw_answer.replace(/```(html)?/gi, "").replace(/<!--[\s\S]*?-->/g, "").replace(/<![^>]*>/g, "");
for (let element of blockedElements) {
  answer_html = answer_html.replace(new RegExp(`<${element}\\b[\\s\\S]*?<\\/${element}\\s*>`, "gi"), "");
}
answer_html = answer_html.replace(/<[^<>]*>|[<>]/g, rebuildTag).replace(/\s*\n\s*/g, " ").trim();

if (!is_answered) {
  answer_html = `<p>The website search did not return an answer (HTTP ${response_code}). Search again, or choose Not Able to Assist.</p>`;
} else if (answer_html.replace(/<[^>]*>/g, "").trim() === "") {
  answer_html = "<p>The website search returned no readable answer. Search again with different wording.</p>";
}

// --- outputs ----------------------------------------------------------------
// Rendered HTML for the Handle response screen.
ZT.setTransformData("webscraper_answer_html", answer_html);
